pub fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left: usize = 0;
    let mut right: usize = v.len(); // exclusive

    while left < right {
        let mid = left + (right - left) / 2;
        let val = v[mid];

        if val < k {
            left = mid + 1;
        } else if val > k {
            right = mid;
        } else {
            return mid;
        }
    }

    // By the problem's assumption, k appears at least once in v.
    unreachable!("target value k is guaranteed to exist in the array");
}